window.MOTIF_CATALOG_CHUNKS[19]={"cards":[{"id":"ML-T01939","row_version":2,"title":"기억이 불완전한 화자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01934","tag_path":[],"summary":"기억이 불완전한 화자는 과거 사건을 잊거나 뒤섞거나 일부만 떠올려 불확실한 회고를 전달한다. 기억의 공백이나 오류가 핵심인지 확인하고, 기억은 온전하지만 현재의 정보만 부족한 상황과 구별한다.","accent":"#7C808E","tab":"#778F70","facet":"서술·언어·정보","bookmark":"기억이 불완전한 화자","entry_url":"cards/ML-T01939/index.html"},{"id":"ML-T01940","row_version":2,"title":"정보 차이","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"group","parent_id":"ML-F23","tag_path":[],"summary":"정보 차이는 독자와 인물, 또는 인물들 사이에 사건에 관한 지식의 양이나 내용이 다르게 배분된 상태다. 작품을 볼 때 누가 무엇을 언제 아는지와 그 차이가 긴장이나 오해에 실제로 작용하는지를 확인한다.","accent":"#7C808E","tab":"#8B739C","facet":"서술·언어·정보","bookmark":"정보 차이","entry_url":"cards/ML-T01940/index.html"},{"id":"ML-T01941","row_version":2,"title":"독자만 아는 정보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01940","tag_path":[],"summary":"독자만 아는 정보는 독자가 어떤 사실을 알고 있지만 관련 인물은 아직 모르는 구성으로, 기대·긴장·극적 아이러니를 만들 수 있다. 독자가 단지 인물보다 먼저 장면을 보았다는 것만이 아니라, 인물의 판단과 달라지는 지식이 유지되는지 본다.","accent":"#7C808E","tab":"#8B739C","facet":"서술·언어·정보","bookmark":"독자만 아는 정보","entry_url":"cards/ML-T01941/index.html"},{"id":"ML-T01942","row_version":2,"title":"인물만 아는 정보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01940","tag_path":[],"summary":"인물만 아는 정보는 한 인물이 독자나 다른 인물에게 알려지지 않은 사실을 보유한 상태다. 비밀의 존재만으로 분류하지 말고, 그 정보가 특정 인물의 지식으로 제한되어 사건의 해석이나 행동에 영향을 주는지 확인한다.","accent":"#7C808E","tab":"#8B739C","facet":"서술·언어·정보","bookmark":"인물만 아는 정보","entry_url":"cards/ML-T01942/index.html"},{"id":"ML-T01943","row_version":2,"title":"모두 모르는 정보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01940","tag_path":[],"summary":"모두 모르는 정보는 독자와 등장인물 모두에게 핵심 사실이 공개되지 않은 상태로, 발견이나 추론을 통해 뒤늦게 밝혀질 수 있다. 단순히 설명이 없는 주변 세부사항이 아니라, 이후 드러나 사건 이해를 바꾸는 정보인지 살핀다.","accent":"#7C808E","tab":"#8B739C","facet":"서술·언어·정보","bookmark":"모두 모르는 정보","entry_url":"cards/ML-T01943/index.html"},{"id":"ML-T01944","row_version":2,"title":"집단별 정보 분리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01940","tag_path":[],"summary":"집단별 정보 분리는 여러 인물이나 집단이 서로 다른 사실을 알고 있어 전체 상황이 한곳에 모이지 않는 구성이다. 한 인물만 비밀을 가진 경우와 구별해, 정보가 여러 집단에 나뉘고 공유의 부재가 갈등이나 오해를 낳는지 확인한다.","accent":"#7C808E","tab":"#8B739C","facet":"서술·언어·정보","bookmark":"집단별 정보 분리","entry_url":"cards/ML-T01944/index.html"},{"id":"ML-T01945","row_version":2,"title":"오인된 정보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01940","tag_path":[],"summary":"오인된 정보는 인물이나 독자가 단서를 사실과 다르게 해석해 잘못된 이해를 갖게 되는 경우다. 거짓 정보가 의도적으로 주어지는 것과 구별하여, 오해가 어떤 단서와 추론에서 생겼는지 살핀다.","accent":"#7C808E","tab":"#8B739C","facet":"서술·언어·정보","bookmark":"오인된 정보","entry_url":"cards/ML-T01945/index.html"},{"id":"ML-T01946","row_version":2,"title":"감춰진 규칙","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01940","tag_path":[],"summary":"감춰진 규칙은 세계나 상황을 움직이는 조건이 당사자에게 공개되지 않아, 결과를 겪거나 단서를 모은 뒤에야 파악되는 구조다. 단순한 비밀이나 미스터리가 아니라, 그 규칙을 알면 사건의 작동 방식이나 선택의 결과를 이해할 수 있는지 본다.","accent":"#7C808E","tab":"#8B739C","facet":"서술·언어·정보","bookmark":"감춰진 규칙","entry_url":"cards/ML-T01946/index.html"},{"id":"ML-T01947","row_version":2,"title":"정보 조절","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"group","parent_id":"ML-F23","tag_path":[],"summary":"정보 조절은 서술이 사실을 언제, 어떤 양과 방식으로 공개할지 선택해 독자의 이해와 기대를 이끄는 작용이다. 정보가 적다는 사실만으로 판단하지 말고, 공개 순서나 강조·생략이 해석에 영향을 주는지 확인한다.","accent":"#7C808E","tab":"#A58A4E","facet":"서술·언어·정보","bookmark":"정보 조절","entry_url":"cards/ML-T01947/index.html"},{"id":"ML-T01948","row_version":2,"title":"암시","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01947","tag_path":[],"summary":"암시는 사실을 직접 말하지 않고 대사·행동·이미지 같은 단서를 통해 독자가 의미를 추론하게 하는 방식이다. 모호한 표현 전부를 암시로 보지 말고, 이후 맥락과 연결되어 추론 가능한 의미를 형성하는지 살핀다.","accent":"#7C808E","tab":"#A58A4E","facet":"서술·언어·정보","bookmark":"암시","entry_url":"cards/ML-T01948/index.html"},{"id":"ML-T01949","row_version":2,"title":"예고","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01947","tag_path":[],"summary":"예고는 이후 일어날 사건이나 변화의 징후를 앞서 제시해 독자의 기대를 형성하는 방식이다. 앞선 단서가 실제 전개와 의미 있게 연결되는지 확인하고, 단순한 분위기 조성이나 우연한 유사성은 구별한다.","accent":"#7C808E","tab":"#A58A4E","facet":"서술·언어·정보","bookmark":"예고","entry_url":"cards/ML-T01949/index.html"},{"id":"ML-T01950","row_version":2,"title":"미끼 단서","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01947","tag_path":[],"summary":"미끼 단서는 독자를 특정한 해석이나 예상으로 이끌지만, 나중에 그 해석이 빗나갔음이 드러나는 단서다. 처음부터 거짓 정보라고 단정하지 말고, 단서가 오해를 유도한 뒤 어떤 근거로 재해석되는지 본다.","accent":"#7C808E","tab":"#A58A4E","facet":"서술·언어·정보","bookmark":"미끼 단서","entry_url":"cards/ML-T01950/index.html"},{"id":"ML-T01951","row_version":3,"title":"정보 지연","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01947","tag_path":[],"summary":"정보 지연은 이미 일어난 사건이나 중요한 사실의 공개를 뒤로 미뤄 독자가 한동안 결과나 원인을 모르게 하는 구성이다. 서술이 끝내 그 정보를 제공하는지, 단순히 언급하지 않는 정보 생략과 어떻게 다른지 확인한다.","accent":"#7C808E","tab":"#A58A4E","facet":"서술·언어·정보","bookmark":"정보 지연","entry_url":"cards/ML-T01951/index.html"},{"id":"ML-T01952","row_version":2,"title":"정보 생략","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01947","tag_path":[],"summary":"정보 생략은 사건의 일부나 설명을 서술에서 비워 독자가 맥락으로 보충하거나 공백 자체를 해석하게 하는 방식이다. 공개를 잠시 미루는 것과 구분해, 해당 정보가 이후 직접 제시되지 않거나 의도적인 공백으로 남는지 본다.","accent":"#7C808E","tab":"#A58A4E","facet":"서술·언어·정보","bookmark":"정보 생략","entry_url":"cards/ML-T01952/index.html"},{"id":"ML-T01953","row_version":3,"title":"반복 제시","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01947","tag_path":[],"summary":"반복 제시는 동일하거나 유사한 정보·장면·표현을 다시 보여주어 기억을 강화하거나 새로운 의미를 덧붙이는 방식이다. 단순한 반복 재생이나 되풀이 대사와 구별해, 재등장이 강조·비교·재해석 중 어떤 기능을 하는지 확인한다.","accent":"#7C808E","tab":"#A58A4E","facet":"서술·언어·정보","bookmark":"반복 제시","entry_url":"cards/ML-T01953/index.html"},{"id":"ML-T01954","row_version":2,"title":"설명적 서술","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01947","tag_path":[],"summary":"설명적 서술은 배경, 규칙, 인물의 사정처럼 사건 이해에 필요한 내용을 서술자가 직접 풀어 전달하는 방식이다. 설명의 분량보다 설명이 어떤 정보를 제공하는지 살피고, 행동이나 대사로 드러나는 내용과 구분한다.","accent":"#7C808E","tab":"#A58A4E","facet":"서술·언어·정보","bookmark":"설명적 서술","entry_url":"cards/ML-T01954/index.html"},{"id":"ML-T01955","row_version":2,"title":"행동을 통한 설명","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01947","tag_path":[],"summary":"행동을 통한 설명은 인물의 선택과 행동, 그 결과를 보여주어 배경이나 성격, 규칙을 직접 풀이하지 않고 전달하는 방식이다. 행동이 단순히 사건을 진행하는 데 그치지 않고 독자가 추가 정보를 추론하게 하는지 확인한다.","accent":"#7C808E","tab":"#A58A4E","facet":"서술·언어·정보","bookmark":"행동을 통한 설명","entry_url":"cards/ML-T01955/index.html"},{"id":"ML-T01956","row_version":2,"title":"시간의 서술","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"group","parent_id":"ML-F23","tag_path":[],"summary":"시간의 서술은 사건이 일어난 순서와 서술에서 제시되는 순서, 그리고 각 사건에 할애되는 분량의 관계를 다룬다. 시간상 비선형이라는 점만 지목하지 말고, 순서와 속도 조절이 독자의 이해에 어떤 효과를 내는지 본다.","accent":"#7C808E","tab":"#528982","facet":"서술·언어·정보","bookmark":"시간의 서술","entry_url":"cards/ML-T01956/index.html"},{"id":"ML-T01957","row_version":2,"title":"회상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01956","tag_path":[],"summary":"회상은 현재 시점의 서술에서 이전에 일어난 사건이나 경험으로 돌아가 제시하는 방식이다. 과거 사건이 단순히 언급되는 것과 구별해, 장면이나 서술의 흐름이 이전 시점으로 옮겨가 정보를 제공하는지 확인한다.","accent":"#7C808E","tab":"#528982","facet":"서술·언어·정보","bookmark":"회상","entry_url":"cards/ML-T01957/index.html"},{"id":"ML-T01958","row_version":2,"title":"플래시포워드","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01956","tag_path":[],"summary":"플래시포워드는 현재 진행 중인 시간보다 앞선 사건이나 상태를 먼저 보여준 뒤 서술이 이전 시점으로 돌아오는 구성이다. 미래를 막연히 예측하거나 예고하는 대사와 구별해, 이후 시간대의 장면이나 결과가 실제로 선행 제시되는지 본다.","accent":"#7C808E","tab":"#528982","facet":"서술·언어·정보","bookmark":"플래시포워드","entry_url":"cards/ML-T01958/index.html"},{"id":"ML-T01959","row_version":2,"title":"과거와 현재의 교차","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01956","tag_path":[],"summary":"과거와 현재의 교차는 서로 다른 시간대의 장면이나 서술을 번갈아 배치해 사건과 인물의 변화를 연결하는 방식이다. 한 차례 회상만 삽입된 구성과 구별해, 과거와 현재의 전환이 반복되거나 두 시간대의 의미를 비교하도록 짜였는지 살핀다.","accent":"#7C808E","tab":"#528982","facet":"서술·언어·정보","bookmark":"과거와 현재의 교차","entry_url":"cards/ML-T01959/index.html"},{"id":"ML-T01960","row_version":2,"title":"한 사건의 재서술","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01956","tag_path":[],"summary":"한 사건의 재서술은 동일한 사건을 다른 인물의 관점이나 새로운 정보에 따라 다시 전달하는 방식이다. 같은 사건이 단순히 요약되거나 반복되는 경우와 달리, 재서술이 앞선 이해를 수정하거나 서로 다른 해석을 드러내는지 확인한다.","accent":"#7C808E","tab":"#528982","facet":"서술·언어·정보","bookmark":"한 사건의 재서술","entry_url":"cards/ML-T01960/index.html"},{"id":"ML-T01962","row_version":2,"title":"대사 기능","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"group","parent_id":"ML-F23","tag_path":[],"summary":"대사 기능은 인물의 말이 정보 전달, 관계 형성, 의사 표현, 행동 유발 등 장면에서 수행하는 역할을 가리킨다. 대사의 주제나 말투와 구분해, 그 말이 상대나 사건의 다음 전개에 어떤 변화를 일으키는지 본다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"대사 기능","entry_url":"cards/ML-T01962/index.html"},{"id":"ML-T01963","row_version":2,"title":"선언","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01962","tag_path":[],"summary":"선언은 화자가 입장·결심·상태를 공개적으로 밝히거나 말로 어떤 지위를 성립시키는 발화다. 사실을 알리는 설명이나 가벼운 의견과 구별해, 발화 자체가 약속·선포처럼 관계나 상황에 효력을 갖는지 확인한다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"선언","entry_url":"cards/ML-T01963/index.html"},{"id":"ML-T01964","row_version":2,"title":"맹세의 말","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01962","tag_path":[],"summary":"맹세의 말은 화자가 자신의 진실성이나 앞으로의 행동을 엄숙히 보증하며 책임을 받아들이는 발화다. 강한 다짐이나 일상적인 약속과 구별해, 어길 경우의 책임이나 초월적·도덕적 보증이 말에 포함되는지 살핀다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"맹세의 말","entry_url":"cards/ML-T01964/index.html"},{"id":"ML-T01965","row_version":2,"title":"예언의 말","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01962","tag_path":[],"summary":"예언의 말은 아직 일어나지 않은 사건이나 미래의 운명을 사실처럼 제시하는 발화다. 추측이나 계획과 구별해, 말이 예지·계시·예언으로 제시되는지, 이후 전개가 그 실현이나 해석을 다루는지 확인한다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"예언의 말","entry_url":"cards/ML-T01965/index.html"},{"id":"ML-T01966","row_version":2,"title":"유언","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01962","tag_path":[],"summary":"유언은 죽음을 앞두었거나 죽음을 예상하는 인물이 남기는 마지막 뜻·당부·처분의 말이다. 작별 인사나 일반적인 부탁과 구별해, 말하는 이가 이를 최후의 전달로 여기며 뒤에 남을 사람이나 일을 위해 남기는지 본다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"유언","entry_url":"cards/ML-T01966/index.html"},{"id":"ML-T01967","row_version":2,"title":"고백의 말","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01962","tag_path":[],"summary":"고백의 말은 화자가 숨겨온 사실이나 내면의 감정·잘못을 상대에게 털어놓는 발화다. 정보 제공이나 사과와 구별해, 이전에 감춰졌던 개인적 진실을 드러내는 행위가 중심인지 확인한다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"고백의 말","entry_url":"cards/ML-T01967/index.html"},{"id":"ML-T01968","row_version":2,"title":"설득","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01962","tag_path":[],"summary":"설득은 상대의 생각이나 선택을 바꾸기 위해 이유·감정·신뢰를 동원하는 발화 행위다. 단순한 주장이나 설명과 구별해, 말의 목적이 청자의 동의나 행동을 얻는 데 있는지 본다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"설득","entry_url":"cards/ML-T01968/index.html"},{"id":"ML-T01969","row_version":2,"title":"도발","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01962","tag_path":[],"summary":"도발은 상대의 감정이나 자존심을 자극해 반응, 대결, 실수를 끌어내려는 발화다. 모욕적인 말투 자체가 아니라, 상대를 움직이거나 갈등을 키우려는 의도가 장면에서 기능하는지 살핀다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"도발","entry_url":"cards/ML-T01969/index.html"},{"id":"ML-T01970","row_version":2,"title":"명령","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01962","tag_path":[],"summary":"명령은 화자가 상대에게 특정 행동을 하거나 멈추도록 요구하는 발화다. 권한 있는 지시나 부탁과 구별할 때는 문장의 겉모양보다 상대의 선택을 제한하는 요구인지와 거부의 결과가 제시되는지를 본다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"명령","entry_url":"cards/ML-T01970/index.html"},{"id":"ML-T01971","row_version":2,"title":"거절","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01962","tag_path":[],"summary":"거절은 제안·요청·명령을 받아들이지 않겠다는 의사를 밝히는 발화다. 단순한 망설임이나 반대 의견과 구별해, 상대가 요구한 응답이나 행동을 거부하는 것이 장면의 핵심인지 확인한다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"거절","entry_url":"cards/ML-T01971/index.html"},{"id":"ML-T01972","row_version":2,"title":"문체·말투","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"group","parent_id":"ML-F23","tag_path":[],"summary":"문체와 말투는 어휘 선택, 문장 구성, 표현의 격식과 리듬이 만드는 언어적 인상이다. 화자의 성격이나 내용 자체와 동일시하지 말고, 반복되는 표현 방식이 서술이나 발화에 어떤 목소리를 형성하는지 살핀다.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"문체·말투","entry_url":"cards/ML-T01972/index.html"},{"id":"ML-T01973","row_version":2,"title":"구어체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01972","tag_path":[],"summary":"구어체는 일상 대화에서 쓰는 어휘와 어순, 축약과 생략을 살린 말하기 중심의 표현이다. 대사에 쓰였다는 이유만으로 구어체라 하지 말고, 문장 전반이 실제 발화의 자연스러운 리듬과 어법을 따르는지 확인한다.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"구어체","entry_url":"cards/ML-T01973/index.html"},{"id":"ML-T01974","row_version":2,"title":"문어체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01972","tag_path":[],"summary":"문어체는 말보다 글에 어울리는 정돈된 어휘와 문장 구조를 사용하는 표현 방식이다. 격식 있는 내용이나 긴 문장만으로 판단하지 말고, 서술과 발화의 어법이 문장어의 관습을 따르는지 살핀다.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"문어체","entry_url":"cards/ML-T01974/index.html"},{"id":"ML-T01975","row_version":2,"title":"운문체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01972","tag_path":[],"summary":"운문체는 리듬·운율·행갈이·반복 같은 시적 형식과 압축된 표현을 중심으로 문장을 구성하는 방식이다. 비유가 많거나 감정적인 산문과 구별해, 언어의 배열과 리듬 자체가 운문적 구조를 이루는지 확인한다.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"운문체","entry_url":"cards/ML-T01975/index.html"},{"id":"ML-T01976","row_version":2,"title":"간결한 문체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01972","tag_path":[],"summary":"간결한 문체는 짧고 절제된 문장과 적은 수식으로 핵심 정보나 인상을 전달하는 표현 방식이다. 단순히 문장 길이가 짧은 한 대목이 아니라, 작품의 서술이나 발화에서 꾸준히 군더더기를 줄이는 경향이 있는지 본다.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"간결한 문체","entry_url":"cards/ML-T01976/index.html"},{"id":"ML-T01977","row_version":2,"title":"장황한 문체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01972","tag_path":[],"summary":"장황한 문체는 세부 설명과 수식, 여담을 길게 덧붙여 문장을 확장한다. 분량이 많다는 이유만으로 붙이지 말고, 말의 우회와 과잉이 서술의 리듬이나 인물의 목소리를 이루는지 살펴라.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"장황한 문체","entry_url":"cards/ML-T01977/index.html"},{"id":"ML-T01978","row_version":2,"title":"건조한 문체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01972","tag_path":[],"summary":"건조한 문체는 감정 표현과 수식을 절제하고 사실이나 행동을 간결하게 전달한다. 비극적 사건을 다룬다는 이유로 분류하지 말고, 서술의 어조가 감정적 평가를 유보하는지 기준으로 삼아라.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"건조한 문체","entry_url":"cards/ML-T01978/index.html"},{"id":"ML-T01979","row_version":3,"title":"고어체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01972","tag_path":[],"summary":"고어체는 현대 일상어와 다른 옛 어휘·어미·문장 구조를 사용해 시대감이나 격식을 만든다. 잔혹함을 뜻하는 ‘고어(gore)’와 구별하고, 작품 전체의 문체인지 일부 대사에 국한되는지도 확인하라.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"고어체","entry_url":"cards/ML-T01979/index.html"},{"id":"ML-T01980","row_version":2,"title":"방언","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01972","tag_path":[],"summary":"방언은 특정 지역이나 사회 집단에서 쓰이는 어휘·발음·문법을 대사나 서술에 반영한다. 단순한 비표준 표현이나 말투 차이만으로 단정하지 말고, 지역·집단과 연결된 언어 특징이 드러나는지 살펴라.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"방언","entry_url":"cards/ML-T01980/index.html"},{"id":"ML-T01981","row_version":2,"title":"존대 표현","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01972","tag_path":[],"summary":"존대 표현은 높임말과 호칭, 종결 어미를 통해 대화 상대에 대한 예우나 사회적 관계를 나타낸다. 단순히 공손한 태도와 혼동하지 말고, 실제 언어 형식이 위계·거리·관계 변화를 표시하는지 기준으로 삼아라.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"존대 표현","entry_url":"cards/ML-T01981/index.html"},{"id":"ML-T01961","row_version":2,"title":"의식의 흐름","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01972","tag_path":[],"summary":"의식의 흐름은 생각과 감각, 기억이 논리적인 설명 순서보다 마음속 연상에 따라 이어지는 방식으로 내면을 드러낸다. 과거 회상이나 독백 일반과 구별해, 사고의 비약과 주관적 연결이 서술의 구조를 이루는지 확인하라.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"의식의 흐름","entry_url":"cards/ML-T01961/index.html"},{"id":"ML-T01982","row_version":3,"title":"수사·언어유희","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"group","parent_id":"ML-F23","tag_path":[],"summary":"수사·언어유희는 표현의 의미·소리·구조를 비틀거나 강조해 독자의 해석과 인상을 조정하는 기법이다. 단순히 인상적인 문장이나 말장난 하나를 가리키지 말고, 어떤 언어적 효과가 반복되거나 의미 있게 쓰이는지 살펴라.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"수사·언어유희","entry_url":"cards/ML-T01982/index.html"},{"id":"ML-T01983","row_version":2,"title":"직유","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01982","tag_path":[],"summary":"직유는 한 대상을 ‘처럼’, ‘같이’ 등의 표지로 다른 대상에 빗대어 공통된 특징을 드러낸다. 유사성이 암시될 뿐 비교 표지가 없는 은유와 구분해, 문장에 명시적인 비교가 있는지 확인하라.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"직유","entry_url":"cards/ML-T01983/index.html"},{"id":"ML-T01984","row_version":2,"title":"은유","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01982","tag_path":[],"summary":"은유는 한 대상을 다른 대상의 이름이나 속성으로 표현해 둘 사이의 유사성을 직접 겹쳐 보인다. ‘처럼’ 같은 비교 표지가 있는 직유나, 유사성보다 실제 인접 관계를 바탕으로 한 환유와 구분하라.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"은유","entry_url":"cards/ML-T01984/index.html"},{"id":"ML-T01985","row_version":2,"title":"환유","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01982","tag_path":[],"summary":"환유는 서로 인접하거나 관습적으로 연결된 대상 가운데 하나를 들어 다른 대상을 가리킨다. 부분이 전체를 대신하는 제유와 구별해, 표현의 연결 근거가 부분·전체 관계인지 다른 연관성인지 따져라.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"환유","entry_url":"cards/ML-T01985/index.html"},{"id":"ML-T01986","row_version":2,"title":"제유","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01982","tag_path":[],"summary":"제유는 부분으로 전체를, 또는 전체로 그 일부를 나타내는 표현이다. 관련된 사물이나 장소로 대상을 대신하는 환유와 혼동하지 말고, 두 대상 사이에 포함 관계가 성립하는지 확인하라.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"제유","entry_url":"cards/ML-T01986/index.html"},{"id":"ML-T01987","row_version":2,"title":"반어","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01982","tag_path":[],"summary":"반어는 말의 표면적 뜻과 화자가 전달하려는 뜻이 어긋나도록 표현하는 방식이다. 단순한 거짓말이나 농담으로 분류하지 말고, 맥락이 말뜻의 반대나 비판적 의도를 드러내는지 살펴라.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"반어","entry_url":"cards/ML-T01987/index.html"},{"id":"ML-T01988","row_version":2,"title":"역설","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01982","tag_path":[],"summary":"역설은 겉으로는 모순되어 보이는 말에 더 깊은 진실이나 통찰을 담는 표현이다. 사실과 반대되는 말을 통해 의도를 비추는 반어와 구별해, 모순된 두 관념이 함께 성립하는 의미를 만드는지 확인하라.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"역설","entry_url":"cards/ML-T01988/index.html"},{"id":"ML-T01989","row_version":2,"title":"과장법","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01982","tag_path":[],"summary":"과장법은 대상의 크기·수·정도·중요성을 실제보다 크게 또는 작게 표현해 인상을 강화한다. 문자 그대로의 사실 진술로 읽을 표현과 구분하고, 맥락상 비현실적인 확대나 축소가 강조 효과를 내는지 판단하라.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"과장법","entry_url":"cards/ML-T01989/index.html"},{"id":"ML-T01990","row_version":3,"title":"말장난","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01982","tag_path":[],"summary":"소리·철자·뜻의 겹침이나 엇갈림을 이용해 두 가지 이상의 해석을 만드는 언어 표현을 찾는 분류다.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"말장난","entry_url":"cards/ML-T01990/index.html"},{"id":"ML-T01991","row_version":2,"title":"중의성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01982","tag_path":[],"summary":"중의성은 한 표현이 문맥에 따라 둘 이상의 의미로 해석될 수 있는 성질이다. 독자가 실제로 가능한 복수의 뜻을 읽어낼 수 있어야 하며, 단순히 뜻이 불분명하거나 설명이 부족한 문장과 구별하라.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"중의성","entry_url":"cards/ML-T01991/index.html"},{"id":"ML-T01992","row_version":2,"title":"반복법","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01982","tag_path":[],"summary":"반복법은 같은 말이나 문장 구조를 거듭 사용해 리듬·강조·정서적 누적을 만드는 표현 기법이다. 우연한 재등장이나 정보 전달을 위한 반복과 구분해, 반복 자체가 의미나 효과를 보태는지 살펴라.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"반복법","entry_url":"cards/ML-T01992/index.html"},{"id":"ML-T01993","row_version":2,"title":"언어 장치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"group","parent_id":"ML-F23","tag_path":[],"summary":"언어 장치는 단어와 문장, 말하기 규칙을 활용해 의미·관계·정보를 조직하거나 변화시키는 표현 수단이다. 특정 수사법 하나에 한정하지 말고, 언어의 선택이나 규칙이 작품의 전달 방식에 실제 영향을 주는지 기준으로 삼아라.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"언어 장치","entry_url":"cards/ML-T01993/index.html"},{"id":"ML-T01994","row_version":2,"title":"이름의 의미","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01993","tag_path":[],"summary":"이름의 의미는 인물·장소·사물의 이름에 담긴 뜻이나 연상이 해석에 보탬을 주는 방식이다. 이름의 어원이나 뜻을 임의로 추측하지 말고, 작품 안에서 그 의미가 성격·주제·사건과 연결되는 근거를 확인하라.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"이름의 의미","entry_url":"cards/ML-T01994/index.html"},{"id":"ML-T01995","row_version":3,"title":"호칭 변화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01993","tag_path":[],"summary":"호칭 변화는 인물 사이에서 이름·직함·친족어·대명사 등의 부르는 방식이 달라지는 일이다. 단순한 표기 변화가 아니라 관계·권력·친밀감의 이동을 드러내는지 대화 맥락을 살펴라.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"호칭 변화","entry_url":"cards/ML-T01995/index.html"},{"id":"ML-T01996","row_version":2,"title":"말버릇","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01993","tag_path":[],"summary":"말버릇은 인물이 자주 쓰는 어휘·어미·감탄사·문장 패턴으로, 반복되어 그 인물의 말투를 식별하게 한다. 한 번의 유행어 사용만으로 분류하지 말고, 반복성과 인물의 언어적 특징을 확인하라.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"말버릇","entry_url":"cards/ML-T01996/index.html"},{"id":"ML-T01997","row_version":2,"title":"금지어","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01993","tag_path":[],"summary":"금지어는 특정 인물이나 집단이 말하거나 쓰지 못하도록 정해진 단어 또는 표현이다. 단순한 욕설·비속어와 구별해, 작품 안에서 금지 규칙과 그 위반 또는 회피가 의미를 갖는지 살펴라.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"금지어","entry_url":"cards/ML-T01997/index.html"},{"id":"ML-T01998","row_version":2,"title":"암호문","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01993","tag_path":[],"summary":"암호문은 정해진 규칙이나 열쇠를 적용해야 본래 내용을 읽을 수 있는 메시지다. 난해하거나 생략된 문장과 구별하고, 해독 가능한 체계와 감춰진 정보가 존재하는지 기준으로 삼아라.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"암호문","entry_url":"cards/ML-T01998/index.html"},{"id":"ML-T01999","row_version":2,"title":"오역","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01993","tag_path":[],"summary":"오역은 한 언어의 발화나 문장을 다른 언어로 옮기는 과정에서 원래 의미가 잘못 전달된 결과다. 의도적인 말장난이나 서로 다른 언어를 이해하지 못하는 상황과 구분해, 번역 내용과 원문의 뜻이 어긋나는지 확인하라.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"오역","entry_url":"cards/ML-T01999/index.html"},{"id":"ML-T02000","row_version":2,"title":"다언어 대화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01993","tag_path":[],"summary":"다언어 대화는 대화 중 둘 이상의 언어가 사용되며, 화자나 청자의 언어 지식이 소통 방식에 영향을 주는 장면이나 방식이다. 번역문에 여러 언어가 병기된 경우만으로 단정하지 말고, 언어 선택과 이해 여부가 실제 대화에 작용하는지 살펴라.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"다언어 대화","entry_url":"cards/ML-T02000/index.html"},{"id":"ML-T02001","row_version":3,"title":"침묵하는 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01993","tag_path":[],"summary":"침묵하는 인물은 말로 대답하거나 발화하지 않는 상태가 인물의 표현 방식이나 장면의 의미에 지속적으로 작용하는 경우를 가리킨다. 잠깐 말을 멈춘 인물과 구분해, 침묵이 선택·제약·반응으로 읽히며 서사에서 기능하는지 확인하라.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"침묵하는 인물","entry_url":"cards/ML-T02001/index.html"},{"id":"ML-T02002","row_version":2,"title":"소리의 위치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"group","parent_id":"ML-F24","tag_path":[],"summary":"소리의 위치는 소리가 이야기 세계 안에서 어디에 속하고 누가 들을 수 있는지를 가리킨다. 장면을 설명할 때는 소리의 발생 장소와 청취자를 함께 살피고, 음량이나 방향만 다루는 경우와 구별한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"소리의 위치","entry_url":"cards/ML-T02002/index.html"},{"id":"ML-T02003","row_version":2,"title":"극중음","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02002","tag_path":[],"summary":"극중음은 이야기 세계 안에서 실제로 발생해 장면 속 인물이 들을 수 있는 소리다. 라디오나 악기처럼 장면 안의 원천이 확인되거나 암시될 때 적용하고, 관객에게만 들리는 배경 음악과 구별한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"극중음","entry_url":"cards/ML-T02003/index.html"},{"id":"ML-T02004","row_version":2,"title":"비극중음","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02002","tag_path":[],"summary":"비극중음은 이야기 세계 바깥에서 관객에게 전달되는 음악이나 효과음으로, 장면 속 인물은 보통 듣지 못한다. 인물의 반응이 없고 서술이나 분위기를 돕는 소리에 적용하며, 화면 안에서 연주되는 곡과 구별한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"비극중음","entry_url":"cards/ML-T02004/index.html"},{"id":"ML-T02005","row_version":2,"title":"인물의 내적 소리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02002","tag_path":[],"summary":"인물의 내적 소리는 생각, 기억, 환청처럼 특정 인물의 주관적 청각 경험으로 제시되는 소리다. 그 인물의 인식에만 묶여 있음을 장면이 드러낼 때 적용하고, 모두가 들을 수 있는 극중음이나 관객용 음악과 구별한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"인물의 내적 소리","entry_url":"cards/ML-T02005/index.html"},{"id":"ML-T02006","row_version":2,"title":"화면 밖 소리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02002","tag_path":[],"summary":"화면 밖 소리는 장면의 시야에는 보이지 않지만 이야기 공간 안에서 발생하는 소리다. 인물이 듣거나 장면의 공간감과 연결될 때 적용하고, 이야기 세계에 속하지 않는 배경 음악과 구별한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"화면 밖 소리","entry_url":"cards/ML-T02006/index.html"},{"id":"ML-T02007","row_version":2,"title":"원인 불명 소리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02002","tag_path":[],"summary":"원인 불명 소리는 발생원이 밝혀지지 않은 채 들려 긴장이나 호기심을 만드는 소리다. 작품이 소리의 출처를 의도적으로 보류할 때 적용하며, 단지 화면 밖에 있다는 이유만으로 해당하지는 않는다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"원인 불명 소리","entry_url":"cards/ML-T02007/index.html"},{"id":"ML-T02008","row_version":2,"title":"소리의 공간 이동","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02002","tag_path":[],"summary":"소리의 공간 이동은 소리가 한 위치에서 다른 위치로 옮겨가는 듯 들리도록 방향과 거리를 변화시키는 연출이다. 이동 경로가 청각적으로 추적될 때 적용하고, 음량만 커지거나 작아지는 변화와 구별한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"소리의 공간 이동","entry_url":"cards/ML-T02008/index.html"},{"id":"ML-T02009","row_version":2,"title":"음향 장치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"group","parent_id":"ML-F24","tag_path":[],"summary":"음향 장치는 소리의 유무와 크기, 질감, 잔향 같은 청각 요소를 조절해 장면의 인상이나 이해를 이끄는 방식이다. 개별 소리의 표현 효과를 분석할 때 적용하고, 선율이나 화성의 구조를 중심으로 한 음악 분석과 구별한다.","accent":"#8A7893","tab":"#778F70","facet":"소리·음악","bookmark":"음향 장치","entry_url":"cards/ML-T02009/index.html"},{"id":"ML-T02010","row_version":2,"title":"침묵","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02009","tag_path":[],"summary":"침묵은 소리를 비우거나 주변 소리를 크게 줄여 그 공백 자체를 두드러지게 하는 연출이다. 침묵 전후의 긴장이나 인물의 반응이 의미를 만들 때 적용하고, 단순한 무음 구간과 구별한다.","accent":"#8A7893","tab":"#778F70","facet":"소리·음악","bookmark":"침묵","entry_url":"cards/ML-T02010/index.html"},{"id":"ML-T02011","row_version":2,"title":"갑작스러운 큰 소리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02009","tag_path":[],"summary":"갑작스러운 큰 소리는 낮거나 조용한 상태 뒤에 큰 음량의 소리를 급격히 제시해 청자를 놀라게 하는 장치다. 급격한 대비와 충격 효과가 핵심일 때 적용하고, 서서히 커지는 소리와 구별한다.","accent":"#8A7893","tab":"#778F70","facet":"소리·음악","bookmark":"갑작스러운 큰 소리","entry_url":"cards/ML-T02011/index.html"},{"id":"ML-T02012","row_version":2,"title":"점진적 음량 증가","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02009","tag_path":[],"summary":"점진적 음량 증가는 소리가 일정한 시간에 걸쳐 점점 크게 들리도록 만드는 변화다. 음량의 누적이 긴장이나 주목을 이끌 때 적용하고, 음높이·속도·편성만 커지는 변화와 구별한다.","accent":"#8A7893","tab":"#778F70","facet":"소리·음악","bookmark":"점진적 음량 증가","entry_url":"cards/ML-T02012/index.html"},{"id":"ML-T02013","row_version":2,"title":"소리의 왜곡","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02009","tag_path":[],"summary":"소리의 왜곡은 음높이, 음색, 속도, 선명도 등을 변형해 원래 소리를 낯설거나 불안정하게 들리게 하는 처리다. 변형된 질감 자체가 표현 효과를 낼 때 적용하고, 단순한 음량 조절이나 공간 잔향과 구별한다.","accent":"#8A7893","tab":"#778F70","facet":"소리·음악","bookmark":"소리의 왜곡","entry_url":"cards/ML-T02013/index.html"},{"id":"ML-T02014","row_version":3,"title":"잔향","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02009","tag_path":[],"summary":"잔향은 소리가 멈춘 뒤 공간 안에서 반사되어 짧게 이어지는 여운이다. 공간의 크기나 재질을 느끼게 하는 지속적인 울림에 적용하고, 소리가 분명한 간격을 두고 반복되는 메아리와 구별한다.","accent":"#8A7893","tab":"#778F70","facet":"소리·음악","bookmark":"잔향","entry_url":"cards/ML-T02014/index.html"},{"id":"ML-T02015","row_version":2,"title":"메아리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02009","tag_path":[],"summary":"메아리는 소리가 반사되어 원음과 구별되는 반복이나 되울림으로 돌아오는 현상이다. 원음 뒤에 식별 가능한 되풀이가 들릴 때 적용하고, 반사가 섞여 소리가 길게 남는 잔향과 구별한다.","accent":"#8A7893","tab":"#778F70","facet":"소리·음악","bookmark":"메아리","entry_url":"cards/ML-T02015/index.html"},{"id":"ML-T02016","row_version":2,"title":"소리의 겹침","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02009","tag_path":[],"summary":"소리의 겹침은 둘 이상의 소리나 음향층을 동시에 배치해 복합적인 청각 장면을 만드는 방식이다. 각 소리가 동시 발생하며 서로 다른 층으로 들릴 때 적용하고, 차례로 이어지는 소리나 하나의 소리를 변형한 경우와 구별한다.","accent":"#8A7893","tab":"#778F70","facet":"소리·음악","bookmark":"소리의 겹침","entry_url":"cards/ML-T02016/index.html"},{"id":"ML-T02017","row_version":2,"title":"음향 대비","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02009","tag_path":[],"summary":"음향 대비는 서로 다른 음량, 음색, 밀도 또는 소리의 유무를 맞붙여 차이를 두드러지게 하는 연출이다. 인접한 소리 사이의 차이가 효과를 만들 때 적용하고, 한 소리의 점진적 변화와 구별한다.","accent":"#8A7893","tab":"#778F70","facet":"소리·음악","bookmark":"음향 대비","entry_url":"cards/ML-T02017/index.html"},{"id":"ML-T02018","row_version":3,"title":"음악의 기능","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"group","parent_id":"ML-F24","tag_path":[],"summary":"음악의 기능은 음악이 장면의 감정, 정보, 인물이나 장소의 인식을 어떻게 이끄는지를 설명한다. 음악이 서사에서 맡는 역할을 분석할 때 적용하고, 곡의 형식이나 음향 자체를 기술하는 항목과 구별한다.","accent":"#8A7893","tab":"#8B739C","facet":"소리·음악","bookmark":"음악의 기능","entry_url":"cards/ML-T02018/index.html"},{"id":"ML-T02019","row_version":2,"title":"인물 테마","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02018","tag_path":[],"summary":"인물 테마는 특정 인물과 연관되어 등장하거나 변주되는 음악적 소재다. 인물의 등장이나 상태 변화와 반복적으로 연결될 때 적용하고, 단순히 인물이 나오는 장면에 우연히 흐르는 음악과 구별한다.","accent":"#8A7893","tab":"#8B739C","facet":"소리·음악","bookmark":"인물 테마","entry_url":"cards/ML-T02019/index.html"},{"id":"ML-T02020","row_version":2,"title":"장소 테마","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02018","tag_path":[],"summary":"장소 테마는 특정 장소나 공간을 식별하게 하는 음악적 소재다. 장소의 재등장과 음악이 반복적으로 연결될 때 적용하고, 장소의 분위기만 일반적으로 묘사하는 배경 음악과 구별한다.","accent":"#8A7893","tab":"#8B739C","facet":"소리·음악","bookmark":"장소 테마","entry_url":"cards/ML-T02020/index.html"},{"id":"ML-T02021","row_version":2,"title":"관계 테마","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02018","tag_path":[],"summary":"관계 테마는 둘 이상의 인물 사이의 유대나 갈등을 음악적으로 표시하는 소재다. 특정 관계의 변화와 음악의 등장 또는 변주가 연결될 때 적용하고, 한 인물만을 가리키는 테마와 구별한다.","accent":"#8A7893","tab":"#8B739C","facet":"소리·음악","bookmark":"관계 테마","entry_url":"cards/ML-T02021/index.html"},{"id":"ML-T02022","row_version":2,"title":"반복 주제","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02018","tag_path":[],"summary":"반복 주제는 작품 안에서 되풀이되어 장면이나 의미를 서로 연결하는 선율 또는 음악적 소재다. 반복될 때마다 연상이나 의미가 축적되는 경우 적용하고, 구조상 되풀이될 뿐 별도 연관성이 없는 반주 패턴과 구별한다.","accent":"#8A7893","tab":"#8B739C","facet":"소리·음악","bookmark":"반복 주제","entry_url":"cards/ML-T02022/index.html"},{"id":"ML-T02023","row_version":2,"title":"위험 예고 음악","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02018","tag_path":[],"summary":"위험 예고 음악은 위협이 드러나기 전이나 다가오는 동안 위험을 감지하게 하는 음악이다. 관객의 경계심을 높이거나 위험의 도래를 암시할 때 적용하고, 위험이 이미 발생한 뒤 충격을 강조하는 음악과 구별한다.","accent":"#8A7893","tab":"#8B739C","facet":"소리·음악","bookmark":"위험 예고 음악","entry_url":"cards/ML-T02023/index.html"},{"id":"ML-T02024","row_version":2,"title":"감정 증폭 음악","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02018","tag_path":[],"summary":"감정 증폭 음악은 장면에 드러난 감정을 음악으로 더 강하게 느끼게 하는 방식이다. 음악이 인물의 정서나 장면의 정서적 강도를 따라 높일 때 적용하고, 감정과 의도적으로 어긋나는 음악과 구별한다.","accent":"#8A7893","tab":"#8B739C","facet":"소리·음악","bookmark":"감정 증폭 음악","entry_url":"cards/ML-T02024/index.html"},{"id":"ML-T02025","row_version":2,"title":"감정과 대비되는 음악","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02018","tag_path":[],"summary":"감정과 대비되는 음악은 장면이나 인물의 감정과 다른 정서적 성격의 음악을 함께 놓는 방식이다. 이 어긋남이 아이러니나 불편함 같은 의미를 만들 때 적용하고, 감정을 그대로 강화하는 음악과 구별한다.","accent":"#8A7893","tab":"#8B739C","facet":"소리·음악","bookmark":"감정과 대비되는 음악","entry_url":"cards/ML-T02025/index.html"},{"id":"ML-T02026","row_version":2,"title":"곡의 구성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"group","parent_id":"ML-F24","tag_path":[],"summary":"곡의 구성은 한 곡을 이루는 구간과 그 배열, 반복 관계를 가리킨다. 음악 작품의 형식과 구간 역할을 설명할 때 적용하고, 곡이 장면에서 수행하는 서사적 기능과 구별한다.","accent":"#8A7893","tab":"#A58A4E","facet":"소리·음악","bookmark":"곡의 구성","entry_url":"cards/ML-T02026/index.html"},{"id":"ML-T02027","row_version":2,"title":"도입부","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02026","tag_path":[],"summary":"도입부는 곡의 시작에서 분위기와 리듬, 조성 또는 주요 소재를 제시하는 구간이다. 본격적인 절이나 후렴에 앞서 곡의 바탕을 마련할 때 적용하고, 노래 시작과 동시에 주 구간이 시작되는 경우와 구별한다.","accent":"#8A7893","tab":"#A58A4E","facet":"소리·음악","bookmark":"도입부","entry_url":"cards/ML-T02027/index.html"},{"id":"ML-T02028","row_version":2,"title":"절","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02026","tag_path":[],"summary":"절은 가사와 선율이 각 반복마다 달라지며 곡의 내용을 전개하는 구간이다. 후렴과 대비되는 서술 구간으로 기능할 때 적용하고, 반복되는 핵심 구절을 중심으로 한 후렴과 구별한다.","accent":"#8A7893","tab":"#A58A4E","facet":"소리·음악","bookmark":"절","entry_url":"cards/ML-T02028/index.html"},{"id":"ML-T02029","row_version":2,"title":"프리코러스","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02026","tag_path":[],"summary":"프리코러스는 절과 후렴 사이에서 에너지나 긴장을 끌어올려 후렴으로 연결하는 구간이다. 독립된 연결 구간의 역할이 들릴 때 적용하고, 절의 마지막 부분이나 후렴 자체와 구별한다.","accent":"#8A7893","tab":"#A58A4E","facet":"소리·음악","bookmark":"프리코러스","entry_url":"cards/ML-T02029/index.html"},{"id":"ML-T02030","row_version":2,"title":"후렴","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02026","tag_path":[],"summary":"후렴은 곡에서 반복되며 중심 구절이나 선율을 강조하는 구간이다. 반복성과 핵심 주제의 집중이 두드러질 때 적용하고, 절처럼 반복마다 내용이 전개되는 구간과 구별한다.","accent":"#8A7893","tab":"#A58A4E","facet":"소리·음악","bookmark":"후렴","entry_url":"cards/ML-T02030/index.html"},{"id":"ML-T02031","row_version":3,"title":"브리지","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02026","tag_path":[],"summary":"브리지는 반복된 구간 사이에 새로운 선율이나 화성, 관점을 제시해 곡의 흐름에 변화를 주는 부분이다. 기존 절·후렴과 대비되는 전환 구간일 때 적용하고, 후렴으로 진입시키는 프리코러스와 구별한다.","accent":"#8A7893","tab":"#A58A4E","facet":"소리·음악","bookmark":"브리지","entry_url":"cards/ML-T02031/index.html"},{"id":"ML-T02032","row_version":2,"title":"간주","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02026","tag_path":[],"summary":"간주는 노래 구간 사이에 악기 연주가 중심이 되어 흐름을 잇거나 변화를 주는 부분이다. 가창이 쉬고 반주가 독립된 구간을 이룰 때 적용하고, 곡의 끝을 마무리하는 코다와 구별한다.","accent":"#8A7893","tab":"#A58A4E","facet":"소리·음악","bookmark":"간주","entry_url":"cards/ML-T02032/index.html"},{"id":"ML-T02033","row_version":2,"title":"코다","original":"Coda","aliases":["Coda"],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02026","tag_path":[],"summary":"코다는 곡의 끝에서 종결감을 주며 마무리하는 구간이다. 앞선 주요 구간이 끝난 뒤 음악을 정리하거나 여운을 남길 때 적용하고, 곡 중간에 배치되는 간주와 구별한다.","accent":"#8A7893","tab":"#A58A4E","facet":"소리·음악","bookmark":"코다","entry_url":"cards/ML-T02033/index.html"},{"id":"ML-T02034","row_version":3,"title":"리프","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02026","tag_path":[],"summary":"리프는 곡 안에서 반복되는 짧고 특징적인 선율이나 리듬 패턴이다. 주로 악기 연주가 반복되어 곡의 추진력이나 정체성을 만들 때 적용하고, 가사나 선율의 기억성을 가리키는 훅과 구별한다.","accent":"#8A7893","tab":"#A58A4E","facet":"소리·음악","bookmark":"리프","entry_url":"cards/ML-T02034/index.html"},{"id":"ML-T02035","row_version":2,"title":"훅","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02026","tag_path":[],"summary":"훅은 곡에서 청자의 주의를 붙잡고 기억에 남도록 설계된 선율, 가사, 리듬 또는 소리의 핵심 요소다. 짧고 식별력 있는 요소가 반복되거나 강조될 때 적용하고, 반드시 후렴 전체나 특정 악기 리프를 뜻하는 것으로 한정하지 않는다.","accent":"#8A7893","tab":"#A58A4E","facet":"소리·음악","bookmark":"훅","entry_url":"cards/ML-T02035/index.html"},{"id":"ML-T02036","row_version":2,"title":"음악적 표현","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"group","parent_id":"ML-F24","tag_path":[],"summary":"음악적 표현은 선율, 리듬, 화성, 속도, 편성 등의 선택으로 정서와 움직임을 전달하는 방식이다. 음악의 구성 요소가 어떤 인상을 만드는지 분석할 때 적용하고, 가사 내용이나 장면의 줄거리만으로 감정을 추정하는 경우와 구별한다.","accent":"#8A7893","tab":"#528982","facet":"소리·음악","bookmark":"음악적 표현","entry_url":"cards/ML-T02036/index.html"},{"id":"ML-T02037","row_version":2,"title":"장조 표현","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02036","tag_path":[],"summary":"장조 표현은 장조의 음계와 화성에서 비롯되는 밝거나 안정된 인상을 활용하는 방식이다. 장조성이 표현에 기여하는지 살필 때 적용하고, 장조라는 이유만으로 작품의 정서가 늘 밝다고 단정하지 않는다.","accent":"#8A7893","tab":"#528982","facet":"소리·음악","bookmark":"장조 표현","entry_url":"cards/ML-T02037/index.html"},{"id":"ML-T02038","row_version":2,"title":"단조 표현","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02036","tag_path":[],"summary":"단조 표현은 단조의 음계와 화성에서 비롯되는 어둡거나 긴장된 인상을 활용하는 방식이다. 단조성이 표현에 기여하는지 살필 때 적용하고, 단조라는 이유만으로 작품의 정서가 늘 슬프다고 단정하지 않는다.","accent":"#8A7893","tab":"#528982","facet":"소리·음악","bookmark":"단조 표현","entry_url":"cards/ML-T02038/index.html"}]}.cards;